CREATE TYPE "CouponType" AS ENUM ('PERCENT','FIXED');
CREATE TABLE "Coupon" ("id" TEXT PRIMARY KEY,"code" TEXT UNIQUE NOT NULL,"type" "CouponType" NOT NULL,"value" DECIMAL(12,2) NOT NULL,"minOrderValue" DECIMAL(12,2),"maxUses" INTEGER,"usedCount" INTEGER NOT NULL DEFAULT 0,"startsAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"endsAt" TIMESTAMP(3),"active" BOOLEAN NOT NULL DEFAULT true,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "CouponRedemption" ("id" TEXT PRIMARY KEY,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"couponId" TEXT NOT NULL,"userId" TEXT NOT NULL,"orderId" TEXT UNIQUE NOT NULL, CONSTRAINT "CouponRedemption_couponId_fkey" FOREIGN KEY ("couponId") REFERENCES "Coupon"("id") ON DELETE RESTRICT, CONSTRAINT "CouponRedemption_userId_fkey" FOREIGN KEY ("userId") REFERENCES "User"("id") ON DELETE RESTRICT, CONSTRAINT "CouponRedemption_orderId_fkey" FOREIGN KEY ("orderId") REFERENCES "Order"("id") ON DELETE RESTRICT, UNIQUE("couponId","userId"));
CREATE TABLE "Notification" ("id" TEXT PRIMARY KEY,"type" TEXT NOT NULL,"title" TEXT NOT NULL,"body" TEXT NOT NULL,"data" JSONB,"readAt" TIMESTAMP(3),"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"userId" TEXT NOT NULL, CONSTRAINT "Notification_userId_fkey" FOREIGN KEY ("userId") REFERENCES "User"("id") ON DELETE CASCADE);
CREATE INDEX "Notification_userId_readAt_createdAt_idx" ON "Notification"("userId","readAt","createdAt");
CREATE TABLE "UserConsent" ("id" TEXT PRIMARY KEY,"type" TEXT NOT NULL,"version" TEXT NOT NULL,"grantedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"revokedAt" TIMESTAMP(3),"userId" TEXT NOT NULL, CONSTRAINT "UserConsent_userId_fkey" FOREIGN KEY ("userId") REFERENCES "User"("id") ON DELETE CASCADE, UNIQUE("userId","type","version"));
CREATE TABLE "AuditLog" ("id" TEXT PRIMARY KEY,"action" TEXT NOT NULL,"entityType" TEXT NOT NULL,"entityId" TEXT,"metadata" JSONB,"ipAddress" TEXT,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"userId" TEXT, CONSTRAINT "AuditLog_userId_fkey" FOREIGN KEY ("userId") REFERENCES "User"("id") ON DELETE SET NULL);
CREATE INDEX "AuditLog_entityType_entityId_createdAt_idx" ON "AuditLog"("entityType","entityId","createdAt");
